import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class DominoOnGraph {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);

        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            String[] parts = br.readLine().split(" ");
            edges[i][0] = Integer.parseInt(parts[0]) - 1; // 0-indexed
            edges[i][1] = Integer.parseInt(parts[1]) - 1;
        }

        if (m == 0) {
            System.out.println(0);
            return;
        }

        int maxDominoes = 0;
        // There are 6 possible dot values (1 to 6).
        // We assign a dot value to each of the n vertices.
        // Total assignments = 6^n. Max n=7, so 6^7 = 279,936.
        int totalAssignments = 1;
        for (int i = 0; i < n; i++) totalAssignments *= 6;

        for (int mask = 0; mask < totalAssignments; mask++) {
            int[] vertexVal = new int[n];
            int temp = mask;
            for (int i = 0; i < n; i++) {
                vertexVal[i] = (temp % 6) + 1; // values 1..6
                temp /= 6;
            }

            // Use a boolean array to track used dominoes.
            // Domino (a, b) with 1 <= a <= b <= 6. Map to index (a-1)*6 + (b-1) or similar.
            // Since 6 is small, we can use a 6x6 boolean array.
            boolean[][] used = new boolean[7][7]; // 1-indexed for dots 1..6
            int count = 0;

            for (int i = 0; i < m; i++) {
                int u = edges[i][0];
                int v = edges[i][1];
                int valU = vertexVal[u];
                int valV = vertexVal[v];

                int a = Math.min(valU, valV);
                int b = Math.max(valU, valV);

                if (!used[a][b]) {
                    used[a][b] = true;
                    count++;
                }
            }

            if (count > maxDominoes) {
                maxDominoes = count;
            }
        }

        System.out.println(maxDominoes);
    }
}
